engineFunctions.tieOn:
function tieOn(name) {
  if (name === 'T4') return G.flags.has('kiri_job') && okId('salaryman') && okId('konbini');
  if (name === 'T6') return wakai();
  if (name === 'N1') return djRoute();
  if (name === 'T7') {
    const other = okId('madam') || G.cat >= CAT_HIGH;
    return okId('grandpa') && other && (G.res.grandpa === 'good' || G.res.madam === 'good' || G.cat >= CAT_HIGH + 1);
  }
  const ids = TIES[name]; if (!ids) return false;
  return ids.every(okId) && ids.some(id => G.res[id] === 'good');
}

engineFunctions.route:
function route() {
  const f = (k) => G.flags.has(k);
  if (f('mi_tell') && !f('mi_rush') && okId('ol')) return 'nanami';
  if (f('konbini_words')) return 'haruka';
  if (djAt2High()) return 'alone'; // DJ（ナツメ）ルート：三好の人生は「ひとり」
  if (okId('konbini')) return 'haruka';
  return 'alone';
}

engineFunctions.djAt2High:
function djAt2High() {
  return typeof G.djAt2 === 'number' && G.djAt2 >= DJ_ROUTE_NEED;
}

engineFunctions.wakai:
function wakai() {
  if (!okId('mother') || !okId('madam')) return false;
  return ['mother_letter', 'n4_bridge', 'sumie_coaster'].filter(f => G.flags.has(f)).length >= 2;
}

engineFunctions.evalTok:
function evalTok(tok) {
  tok = tok.trim(); let neg = false;
  if (tok[0] === '!') { neg = true; tok = tok.slice(1).trim(); }
  let v, m;
  if ((m = tok.match(/^(good|mid|bad|ok):(\w+)$/))) v = m[1] === 'ok' ? okId(m[2]) : G.res[m[2]] === m[1];
  else if ((m = tok.match(/^tie:(T\d)$/))) v = tieOn(m[1]);
  else if ((m = tok.match(/^(dj|cat)\s*(>=|<=|>|<|==)\s*(-?\d+)$/))) {
    const a = G[m[1]], b = +m[3];
    v = m[2] === '>=' ? a >= b : m[2] === '<=' ? a <= b : m[2] === '>' ? a > b : m[2] === '<' ? a < b : a === b;
  }
  else if (tok === 'conn') v = connHigh();
  else if (tok === 'djhigh') v = djHigh();
  else if (tok === 'cathigh') v = G.cat >= CAT_HIGH;
  else if ((m = tok.match(/^route:(\w+)$/))) v = route() === m[1];
  else if ((m = tok.match(/^draw([012])$/))) v = drawLevel() === +m[1];
  else if (tok === 'sayno') v = G.flags.has('hi_no') || G.flags.has('mi_no');
  else if (tok === 'designer') v = designer();
  else if (tok === 'pop_job') v = popJob();
  else if (tok === 'wakai') v = wakai();
  else if (tok === 'djroute') v = djRoute();
  else v = G.flags.has(tok);
  return neg ? !v : v;
}

engineFunctions.cond:
function cond(c) {
  if (typeof c === 'function') { try { return !!c(G); } catch (e) { return false; } }
  return String(c).split('|').some(or => or.split('&').every(evalTok));
}

engineFunctions.applyChoice:
function applyChoice(c) {
  if (c.set) [].concat(c.set).forEach(f => G.flags.add(f));
  if (typeof c.dj === 'number') G.dj += c.dj;
  if (typeof c.cat === 'number') G.cat += c.cat;
  const seg = G.seg;
  if (seg && seg.type === 'visitor' && !c.free) {
    const id = seg.id, cnt = G.counts[id] || (G.counts[id] = { n: 0, g: 0 });
    let m = G.meters[id] || 0;
    const good = c.k === 'just' || (c.k === 'odd' && c.good !== false);
    cnt.n++; if (good) cnt.g++;
    if (typeof c.m === 'number') m += c.m;
    else if (c.k === 'near') m -= 2;
    else if (c.k === 'far') m += 2;
    else if (good) m = m > 0 ? Math.max(0, m - 2) : Math.min(0, m + 2);
    G.meters[id] = Math.max(-8, Math.min(8, m));
    drawMeter(true);
  }
  updateTest();
}

engineFunctions.resultOf:
function resultOf(id) {
  const c = G.counts[id] || { n: 0, g: 0 }, m = Math.abs(G.meters[id] || 0);
  if (c.n === 0) return 'mid';
  if (c.g >= c.n - 1 && m <= 2) return 'good';
  if (c.g <= Math.floor(c.n / 3) || m >= 5) return 'bad';
  return 'mid';
}
